import client from "../client";

const retailerReceiptsAction = (data) => {
    return client.post("/retailers/receipts", data);

};
const retailerReceiptsActionAdmin = (data) => {
    return client.post("/retailers/receipts/admin", data);

};
const retailerReceiptsActionJoint = (data) => {
    return client.post("/retailers/receipts/joint", data);

};

export default {
    retailerReceiptsAction,
    retailerReceiptsActionAdmin,
    retailerReceiptsActionJoint
};
