import React, { useEffect, useState } from 'react'
import InventoryTable from './InventoryTable'
import { useNavigate } from 'react-router-dom';
import { getLoggedInUser } from '../../../helpers/authUtils';
import InventoryFormModal from './InventoryFormModal';
import { Loading } from '../../../components';
import { useDispatch, useSelector } from 'react-redux';
import { getRetailerReceipts } from '../../../redux/retailers/receipts/actions';
import SoldInventoryTable from './SoldInventoryTable';
import ordersApi from '../../../api/orders/ordersApi';
import useApi from '../../../hooks/useApi';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Sold Qty", uid: "purchased_quantity" },
    { name: "Discount Qty", uid: "discount_quantity" },
    { name: "Total Price", uid: "item_price_total" },
    { name: "Item profit", uid: "item_profit" },
    { name: "Unit Qty", uid: "unit_quantity" },
    { name: "Actions", uid: "actions" },
];


function SoldInventoryList() {

    const [openRetailerReceiptFormModal, setopenRetailerReceiptFormModal] = useState(false)
    const navigate = useNavigate()
    const [retailerReceipt, setRetailerReceipt] = useState()
    // const [retailerReceipts, setRetailerReceipts] = useState([])
  
    const [updated, setUpdated] = useState(false)
    const [itemsToDisplay, setitemsToDisplay] = useState(50)
    const [modalTitle, setmodalTitle] = useState("")

    // const retailerReceipts = useSelector((state) => state.RetailerReceipts.retailerReceipts);
    // const loading = useSelector((state) => state.RetailerReceipts.loading);

    const [data, setdata] = useState([])
    const [selectedDates, setSelectedDates] = useState();

    const [user, setUser] = useState()

    const dispatch =useDispatch();


    useEffect(() => {
        setUser(getLoggedInUser())

    }, [])

    useEffect(() => {
        dispatch(getRetailerReceipts({
            "action":"GetRetailerReceipts"
        }))

    }, [])

    const orderItemsApi = useApi(ordersApi.ordersActionAdmin)

    const getCustomerOrderItems = async (user) => {
      
        await orderItemsApi.request({
            "action": "RetrieveCustomerOrderItems"
          
        })
    }


    const getCustomerOrderItemsByDate = async (user) => {
      
        await orderItemsApi.request({
            "action": "RetrieveCustomerOrderItems",
            "filters": {
                "from_date": selectedDates?selectedDates[0]:"",
                "to_date": selectedDates?selectedDates[1]:""
            }
        })
    }

    useEffect(() => {
        if(selectedDates){
            getCustomerOrderItemsByDate()
        }
   
    }, [selectedDates])
    useEffect(()=>{getCustomerOrderItems()},[])
    useEffect(() => {

        if (orderItemsApi.data && orderItemsApi.data.length) {

            setdata(orderItemsApi.data)
        }

        console.log('orderItemsApi.data', orderItemsApi.data)
    }, [orderItemsApi.data])

    const handleEditAction = (item) => {

        setopenRetailerReceiptFormModal(true)

        // setUpdated(false)

        setRetailerReceipt(item)
        setmodalTitle(`${item.title}`)

    }

    const handleAddAction = () => {


        setopenRetailerReceiptFormModal(true)

        setUpdated(false)

        setmodalTitle("Add new department")
        setRetailerReceipt(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/retailers/inventory/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {

        navigate(`/retailers/inventory/delete/${item.id}`)
    }




    useEffect(() => {

    }, [openRetailerReceiptFormModal])





    const handleFilter = (e) => {
        console.log('filter',e)


        const search_param = e

        if ( search_param && search_param !== '') {
            setdata(orderItemsApi.data.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(orderItemsApi.data);
         
            // dispatch()
        }
    

    };

    return orderItemsApi.loading ? <Loading loading={orderItemsApi.loading} /> : (
        <div>

            {openRetailerReceiptFormModal && <InventoryFormModal openEditModal={openRetailerReceiptFormModal} setopenEditModal={setopenRetailerReceiptFormModal} item={retailerReceipt} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <SoldInventoryTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} itemsToDisplay={itemsToDisplay}  setitemsToDisplay={setitemsToDisplay} selectedDates={selectedDates} setSelectedDates={setSelectedDates}/>
        </div>
    )
}

export default SoldInventoryList